function icon(name,cls=''){return `<svg viewBox="0 0 24 24" aria-hidden="true" class="${cls}"><path d="${paths[name]||paths.spark}"/></svg>`}
const btn=(label,action,options={})=>`<button class="btn ${options.cls||''}" data-action="${action}" ${options.attrs||''}>${options.icon?icon(options.icon):''}${label}</button>`;
const options=(obj,current,label='name')=>Object.entries(obj).map(([k,v])=>`<option value="${esc(k)}" ${k===current?'selected':''}>${esc(v[label]||v)}</option>`).join('');
