const ECONOMY_CURRENCIES=Object.freeze({pc:{name:'Cobre',factor:.01},pp:{name:'Prata',factor:.1},pe:{name:'Electro',factor:.5},po:{name:'Ouro',factor:1},pl:{name:'Platina',factor:10}});
function economyEntries(c){if(!Array.isArray(c.economy))c.economy=[];return c.economy;}
function economyTotal(c,type){return economyEntries(c).filter(entry=>entry.type===type&&ECONOMY_CURRENCIES[entry.currency]).reduce((sum,entry)=>sum+(Number(entry.amount)||0)*ECONOMY_CURRENCIES[entry.currency].factor,0);}
function treasureValuePO(c){return Object.entries(ECONOMY_CURRENCIES).reduce((sum,[key,currency])=>sum+(Number(c.coins?.[key])||0)*currency.factor,0);}
function spellPreparedPriority(c,spell){const owners=knownSpellClassIds(c,spell),prepared=(c.prepared||[]).includes(spell.id);return owners.some(id=>id==='special'||id.startsWith('feat:')||id.startsWith('subclass:')||id==='mystic'&&!!arcanumAvailability(c,spell)?.ready||id!=='special'&&id!=='mystic'&&prepared&&((c.spellClasses?.[spell.id]||[]).includes(id)||owners.includes(id)));}
