 if(ctx.kind==='check'&&c.conditions.includes('Envenenado')){disadvantage=true;reasons.push('Envenenado: desvantagem no teste.')}if(ctx.skill==='Furtividade'&&d.armor.stealth){disadvantage=true;reasons.push('Armadura: desvantagem em Furtividade.')}
