 if((['attack','check','save','initiative'].includes(ctx.kind))&&(['str','dex'].includes(ctx.key)||ctx.kind==='initiative')&&d.warnings.some(x=>x.startsWith('Sem treinamento'))){disadvantage=true;reasons.push('Equipamento sem treinamento: desvantagem.')}
 if(ctx.spell&&c.adjust.innate&&ctx.sourceClassId==='feiticeiro'){advantage=true;reasons.push('Feitiçaria Inata: vantagem no ataque mágico.')}
