 if(!ctx.spell&&!ctx.unarmed&&hasFeat012(c,'Presente do Dragão Cromático')&&chroma?.active&&chroma.weaponId===w?.id)parts.push({label:'Infusão Cromática',formula:'1d4',type:chroma.element});
