 '010-battle-enemy':()=>{useKnowYourEnemy(current());render();openModal('Conheça Seu Inimigo','Uso registrado · Ação Bônus',`<p class="reading">O Mestre informa as imunidades, resistências e vulnerabilidades da criatura visível a até 9 metros. O site não cria nem escolhe um alvo.</p>`,btn('Concluir','modal-close',{cls:'primary'}));},
