 '096-goliath-confirm':e=>{const c=current(),variant=e.dataset.variant;if(variant!==c.variant)throw Error('A ancestralidade mudou. Reabra o poder.');const use=useSpecies096(c,'goliath-ancestry'),d=derive(c);closeModal();render();let formula='',label='',subtitle='',message='';if(variant==='Gigante do Fogo'){formula='1d10';label='Combustão do Gigante do Fogo';subtitle='Dano ígneo adicional após acertar um ataque.';}else if(variant==='Gigante da Geada'){formula='1d6';label='Frio do Gigante da Geada';subtitle='Dano gélido adicional e redução de 3 m no deslocamento até o início do seu próximo turno.';}else if(variant==='Gigante da Pedra'){formula='1d12'+(d.m.con>=0?'+':'')+d.m.con;label='Resistência da Pedra';subtitle='Reduza o dano recebido pelo resultado desta rolagem (Reação).';}else if(variant==='Gigante da Tempestade'){formula='1d8';label='Trovão do Gigante da Tempestade';subtitle='Dano trovejante a quem causou dano a até 18 m (Reação).'}else if(variant==='Gigante da Colina'){message='O alvo Grande ou menor atingido pelo ataque recebe a condição Caído.';}else{message='Teleporte-se até 9 m para um espaço desocupado que você possa ver (Ação Bônus).';}if(formula){const r=roll(formula);log(label,r.total,formula,'damage');presentDice(diceFromRoll(r),{label,total:r.total,subtitle:formula},()=>openModal(label,'Uso consumido · '+use.remaining+' usos restantes',`<div class="roll-result"><div class="result-num">${r.total}</div><p>${esc(formula)}</p></div><p class="reading">${esc(subtitle)}</p>`,btn('Concluir','modal-close',{cls:'primary'})));}else openModal(use.name,'Uso consumido · '+use.remaining+' usos restantes',`<p class="reading">${esc(message)}</p>`,btn('Concluir','modal-close',{cls:'primary'}));},
