 '096-advantage-dialog':e=>{const id=e.dataset.id,abilities=['dwarf-poison','halfling-brave'].includes(id)?[['con','Constituição'],['wis','Sabedoria'],['cha','Carisma'],['str','Força'],['dex','Destreza'],['int','Inteligência']]:[['int','Inteligência'],['wis','Sabedoria'],['cha','Carisma']];openModal('Salvaguarda com vantagem','Use apenas quando a característica e o efeito justificarem.',`${selectField('Atributo da salvaguarda','096-save-ability',abilities.map(([k,n])=>`<option value="${k}">${n}</option>`).join(''))}`,`${btn('Cancelar','modal-close',{cls:'ghost'})}${btn('Rolar 2d20','096-advantage-roll',{cls:'primary'})}`);},
