 'coin-convert':()=>{const c=current();c.coins??={pc:0,pp:0,pe:0,po:0,pl:0};const from=$('#coin-convert-from')?.value,to=$('#coin-convert-to')?.value,amount=Math.floor(val($('#coin-convert-amount')?.value,1,999999)),units={pc:1,pp:10,pe:50,po:100,pl:1000};if(!from||!to||from===to){toast('Escolha moedas diferentes para converter.');return}if((c.coins[from]||0)<amount){toast('Saldo insuficiente na moeda de origem.');return}const copper=amount*units[from];if(copper%units[to]!==0){toast('Essa quantidade não permite uma conversão exata. Ajuste o valor.');return}c.coins[from]-=amount;c.coins[to]=(c.coins[to]||0)+copper/units[to];save();render();toast('Conversão realizada!')},
 'economy-add':()=>{const c=current(),type=$('#economy-type')?.value,description=($('#economy-description')?.value||'').trim(),amount=Number($('#economy-amount')?.value),currency=$('#economy-currency')?.value;if(!['gain','expense'].includes(type))throw Error('Escolha ganho ou gasto.');if(!description||description.length>120)throw Error('Descreva a movimentação em até 120 caracteres.');if(!Number.isSafeInteger(amount)||amount<1||amount>999999)throw Error('Informe uma quantidade inteira entre 1 e 999.999.');if(!Object.hasOwn(ECONOMY_CURRENCIES,currency))throw Error('Escolha uma moeda válida.');economyEntries(c);c.coins??={pc:0,pp:0,pe:0,po:0,pl:0};if(c.economy.length>=1000)throw Error('O histórico atingiu o limite de 1.000 movimentações.');const currentAmount=Number(c.coins?.[currency])||0;if(type==='expense'&&currentAmount<amount)throw Error('Saldo insuficiente em '+currency.toUpperCase()+'. Você possui '+fmt(currentAmount)+'.');if(type==='gain'&&currentAmount+amount>999999)throw Error('Esse ganho ultrapassa o limite de moedas dessa categoria.');c.coins[currency]=currentAmount+(type==='gain'?amount:-amount);c.economy.push({id:crypto.randomUUID(),type,description,amount,currency,time:Date.now()});save();render();toast(type==='gain'?'Ganho registrado e adicionado ao Tesouro.':'Gasto registrado e descontado do Tesouro.')},
 'economy-delete':e=>{const c=current();economyEntries(c);c.coins??={pc:0,pp:0,pe:0,po:0,pl:0};const index=c.economy.findIndex(x=>x.id===e.dataset.id)??-1;if(index<0)throw Error('Movimentação não encontrada.');const entry=c.economy[index],currentAmount=Number(c.coins?.[entry.currency])||0;if(entry.type==='gain'&&currentAmount<entry.amount)throw Error('Não é possível desfazer este ganho: parte desse dinheiro já foi utilizada ou convertida.');if(entry.type==='expense'&&currentAmount+entry.amount>999999)throw Error('Não é possível devolver esse valor: o limite dessa moeda seria ultrapassado.');c.coins[entry.currency]=currentAmount+(entry.type==='gain'?-entry.amount:entry.amount);c.economy.splice(index,1);save();render();toast('Movimentação desfeita e saldo atualizado.')},

