 'movement':()=>{const c=current(),d=derive(c),bonuses=[];let speed=d.speed;if(c.speciesId==='golias'&&c.largeForm&&c.level>=5){speed+=3;bonuses.push('Forma Grande: +3 m');}if(String(c.speciesId||'').includes('transmorfo-passos-rapidos')&&c.shiftingActive){speed+=1.5;bonuses.push('Passos Rápidos: +1,5 m');}const special=Object.entries(d.movements||{}).filter(([key,value])=>key!=='fly'&&Number(value)>0).map(([key,value])=>`<div class="movement-detail-row"><span>${esc(({climb:'Escalada',swim:'Natação',burrow:'Escavação'})[key]||key)}</span><strong>${fmt(value)} m</strong></div>`).join('');const form=c.activeForm?`<div class="movement-detail-row"><span>Forma atual · ${esc(c.activeForm.name)}</span><strong>${fmt(c.activeForm.speed)} m</strong></div>`:'';openModal('Seu caminho pela aventura.','Movimento e deslocamento.',`<div class="roll-result"><div class="result-label">Deslocamento terrestre atual</div><div class="result-num">${fmt(Math.max(0,speed))}<small style="font-size:24px"> m</small></div></div>${bonuses.length?`<div class="movement-details">${bonuses.map(x=>`<div class="movement-detail-row"><span>${esc(x)}</span><strong>Ativo</strong></div>`).join('')}</div>`:''}${form||special?`<div class="movement-details">${form}${special}</div>`:''}<p class="reading">Você pode dividir o movimento durante seu turno. Terreno difícil custa um metro adicional por metro. Levantar da condição Caído custa metade do deslocamento. Disparar concede movimento adicional igual ao seu deslocamento.</p>`,btn('Concluir','modal-close',{cls:'primary'}))},
