 'attack':e=>{const c=current(),w=c.weapons[Number(e.dataset.index)],a=attackStats(c,w);if(c.shield&&(a.twoHanded||w.two)){toast('Guarde o escudo para usar esta arma com duas mãos.');return}if(c.conditions.some(x=>['Incapacitado','Inconsciente','Paralisado','Atordoado','Petrificado'].includes(x))){toast('Sua condição impede a ação Atacar.');return}performD20({kind:'attack',key:a.stat,label:a.name,bonus:a.attack,weapon:a})},'attack-thrown':e=>{const c=current(),w={...c.weapons[Number(e.dataset.index)],thrownAttack:true},a=attackStats(c,w);if(!a.thrown)throw Error('Esta arma não possui a propriedade Arremesso.');performD20({kind:'attack',key:a.stat,label:a.name+' · arremesso',bonus:a.attack,weapon:a})},'attack-two-weapon':e=>{const c=current(),index=Number(e.dataset.index),source=c.weapons[index];if(!source||!weaponDefinition(source)?.light)throw Error('O ataque adicional exige uma arma com a propriedade Leve.');if(!hasOtherLightWeapon(c,index))throw Error('Combate com Duas Armas exige duas armas Leves diferentes.');if(!c.dualWieldActive)throw Error('Abra a verificação dos estilos e confirme que está empunhando as duas armas.');const w={...source,twoWeaponExtra:true,otherLightWeapon:true},a=attackStats(c,w);performD20({kind:'attack',key:a.stat,label:a.name+' · ataque adicional',bonus:a.attack,weapon:a})},'style-status':fightingStylesDialog,'combat-tab':e=>{combatMode=e.dataset.tab;render()},
 'unarmed':()=>{const c=current(),d=derive(c);if(cannotAct(c)){toast('Sua condição impede o ataque desarmado.');return;}const fighter=classLevel(c,'guerreiro'),criticalThreshold=fighter>=3&&subclassFor(c,'guerreiro')==='Campeão'?(fighter>=15?18:19):20;performD20({kind:'attack',key:hasClass(c,'monge')?'dex':'str',label:'Ataque desarmado',bonus:d.pb+unarmedMod(c,d),unarmed:true,weapon:{type:'Contundente',formula:unarmedFormula(c,d),criticalThreshold,activeStyles:ownedStyles(c).includes('Combate Desarmado')?['Combate Desarmado · dado de dano aplicado']:[]}})},
