 if(t.id==='level-class'){levelDraft.classId=t.value;levelDraft.hpRoll=null;levelDraft.subclass='';levelDraft.order='';levelDraft.skill='';levelDraft.fightingStyle='';levelDraft.styleAlternative='';levelUpDialog(false);}
 if(t.id==='level-hp-method'){levelDraft.hpMethod=t.value;levelUpDialog(false);}
 if(t.id==='level-asi'){levelDraft.asi=t.value;levelUpDialog(false);}
 const levelKeys={'level-subclass':'subclass','level-order':'order','level-skill':'skill','level-asi-first':'first','level-asi-second':'second','level-feat':'feat'};if(levelKeys[t.id]){levelDraft[levelKeys[t.id]]=t.value;updateLevelPreview();}
